{
  "name": "@azure-rest/ai-vision-face",
  "version": "1.0.0-beta.3",
  "description": "Face API REST Client",
  "engines": {
    "node": ">=22.0.0"
  },
  "sideEffects": false,
  "autoPublish": false,
  "type": "module",
  "keywords": [
    "node",
    "azure",
    "cloud",
    "typescript",
    "browser",
    "isomorphic"
  ],
  "author": "Microsoft Corporation",
  "license": "MIT",
  "files": [
    "dist/",
    "README.md",
    "LICENSE",
    "review/",
    "CHANGELOG.md"
  ],
  "sdk-type": "client",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Azure/azure-sdk-for-js",
    "directory": "sdk/face/ai-vision-face-rest"
  },
  "bugs": {
    "url": "https://github.com/Azure/azure-sdk-for-js/issues"
  },
  "homepage": "https://github.com/Azure/azure-sdk-for-js/tree/main/sdk/face/ai-vision-face-rest/README.md",
  "prettier": "@azure/eslint-plugin-azure-sdk/prettier.json",
  "//metadata": {
    "constantPaths": [
      {
        "path": "src/faceClient.ts",
        "prefix": "userAgentInfo"
      }
    ]
  },
  "dependencies": {
    "@azure-rest/core-client": "^2.1.0",
    "@azure/abort-controller": "^2.1.2",
    "@azure/core-auth": "^1.9.0",
    "@azure/core-lro": "^3.0.0",
    "@azure/core-rest-pipeline": "^1.19.0",
    "@azure/logger": "^1.1.4",
    "tslib": "^2.8.1"
  },
  "devDependencies": {
    "@azure-tools/test-credential": "workspace:^",
    "@azure-tools/test-recorder": "workspace:^",
    "@azure-tools/test-utils-vitest": "workspace:^",
    "@azure/dev-tool": "workspace:^",
    "@azure/eslint-plugin-azure-sdk": "workspace:^",
    "@azure/identity": "catalog:internal",
    "@types/node": "catalog:",
    "@vitest/browser-playwright": "catalog:testing",
    "@vitest/coverage-istanbul": "catalog:testing",
    "cross-env": "catalog:",
    "dotenv": "catalog:testing",
    "eslint": "catalog:",
    "playwright": "catalog:testing",
    "prettier": "^3.2.5",
    "react-native": "catalog:testing",
    "rimraf": "catalog:",
    "typescript": "catalog:",
    "vitest": "catalog:testing"
  },
  "scripts": {
    "build": "npm run clean && dev-tool run build-package && dev-tool run extract-api",
    "build:samples": "tsc -p tsconfig.samples.json",
    "check-format": "prettier --list-different --config ../../../.prettierrc.json --ignore-path ../../../.prettierignore \"src/**/*.{ts,cts,mts}\" \"test/**/*.{ts,cts,mts}\" \"*.{js,cjs,mjs,json}\" ",
    "clean": "rimraf --glob dist dist-browser dist-esm test-dist temp types *.tgz *.log",
    "execute:samples": "echo skipped",
    "extract-api": "rimraf review && dev-tool run extract-api",
    "format": "prettier --write --config ../../../.prettierrc.json --ignore-path ../../../.prettierignore \"src/**/*.{ts,cts,mts}\" \"test/**/*.{ts,cts,mts}\" \"*.{js,cjs,mjs,json}\" ",
    "generate:client": "echo skipped",
    "lint": "eslint package.json src test",
    "lint:fix": "eslint package.json src test --fix --fix-type [problem,suggestion]",
    "pack": "pnpm pack 2>&1",
    "test": "npm run test:node && npm run test:browser",
    "test:browser": "echo skipped",
    "test:node": "dev-tool run build-test --no-browser-test && dev-tool run test:vitest",
    "update-snippets": "dev-tool run update-snippets"
  },
  "//sampleConfiguration": {
    "productName": "Face API",
    "productSlugs": [
      "azure"
    ],
    "disableDocsMs": true,
    "apiRefLink": "https://aka.ms/azsdk-javascript-face-ref",
    "extraFiles": {
      "./samples-dev/data/detection1.jpg": [
        "javascript/data/detection1.jpg",
        "typescript/src/data/detection1.jpg"
      ],
      "./samples-dev/data/detection5.jpg": [
        "javascript/data/detection5.jpg",
        "typescript/src/data/detection5.jpg"
      ],
      "./samples-dev/data/nine-faces.png": [
        "javascript/data/nine-faces.png",
        "typescript/src/data/nine-faces.png"
      ]
    }
  },
  "exports": {
    "./package.json": "./package.json",
    ".": {
      "browser": {
        "types": "./dist/browser/index.d.ts",
        "default": "./dist/browser/index.js"
      },
      "react-native": {
        "types": "./dist/react-native/index.d.ts",
        "default": "./dist/react-native/index.js"
      },
      "import": {
        "types": "./dist/esm/index.d.ts",
        "default": "./dist/esm/index.js"
      },
      "require": {
        "types": "./dist/commonjs/index.d.ts",
        "default": "./dist/commonjs/index.js"
      }
    }
  },
  "main": "./dist/commonjs/index.js",
  "types": "./dist/commonjs/index.d.ts",
  "module": "./dist/esm/index.js",
  "browser": "./dist/browser/index.js",
  "react-native": "./dist/react-native/index.js",
  "imports": {
    "#platform/*": {
      "react-native": "./src/*-react-native.mts",
      "browser": "./src/*-browser.mts",
      "default": "./src/*.ts"
    }
  }
}
